export const REQUEST_COMMENTS={outlets:'No outlet at this table.',lighting:'Too dark to read.',comfort:'This chair is uncomfortable.',noise:'Too loud to concentrate.',atmosphere:'Too quiet. Where’s the vibe?',groupSeating:'We need seats together.',noSeat:'There’s nowhere to sit.',accessibility:'This aisle is too narrow.',blockedRoute:'This walkway is blocked.',bathroom:'There’s no bathroom.',bathroomQueue:'Too few bathrooms.',bathroomAccess:'The bathroom route is blocked.',crowding:'These tables are too close.'};
export function requestComment(g){if(g?.concern?.key==='noise'&&g.type==='remote')return 'Too loud for my meeting.';return REQUEST_COMMENTS[g?.concern?.key]||'This layout needs work.';}
export function requestAction(fix){return ({tableOutlet:'Add table outlet',outlet:'Add outlet','connect-device':'Connect device',deskLamp:'Add reading lamp',comfort:'Improve chair',quiet:'Lower music',divider:'Add divider',music:'Play music',bathroom:'Build bathroom',smallSet:'Add seats',roundSet:'Add group seats',groupSet:'Add group seats',seat:'Use available seat'})[fix?.id]||fix?.label||'Adjust café';}
export function requestTradeoff(fix){return ({tableOutlet:['Charging','Costs money'],outlet:['Charging','Costs money'],'connect-device':['Charging','Seat stays occupied'],deskLamp:['Reading light','Uses floor space'],comfort:['Better posture','Costs money'],quiet:['Focus','Less social vibe'],divider:['Less local noise','Uses floor space'],music:['Social vibe','Less focus'],bathroom:['Longer visits','Less café space'],smallSet:['More seats','Less floor space'],roundSet:['Seats together','Less floor space'],groupSet:['Seats together','Less floor space'],seat:['A place to sit','Fewer free seats']})[fix?.id]||['Customer comfort','Uses budget or space'];}
